import { cva, type VariantProps } from "class-variance-authority";
import {
  Children,
  cloneElement,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  type BlurEvent,
  type FocusEvent,
  Pressable,
  TextInput as RNTextInput,
  View,
} from "react-native";
import Animated, {
  interpolateColor,
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import { useCSSVariable } from "uniwind";
import { cn } from "@/lib/utils";
import {
  Button,
  ButtonIcon,
  type ButtonProps,
  ButtonText,
} from "@/components/ui/button";

// Constants
const ANIMATION_DURATION = 120;

// Types
type InternalInputAddonButtonContextType = VariantProps<
  typeof inputAddonButtonVariants
> &
  Pick<ButtonProps, "variant">;

export type InputProps = Omit<
  React.ComponentPropsWithRef<typeof RNTextInput>,
  "editable"
> & {
  disabled?: boolean;
};

export type InputGroupProps = React.ComponentProps<typeof View> &
  Pick<
    React.ComponentProps<typeof Pressable>,
    | "onPress"
    | "onPressIn"
    | "onPressOut"
    | "onLongPress"
    | "accessibilityRole"
    | "accessibilityState"
    | "accessibilityLabel"
    | "accessibilityHint"
    | "accessible"
    | "hitSlop"
    | "testID"
    | "delayLongPress"
  > & {
    disabled?: boolean;
    invalid?: boolean;
    focused?: boolean;
    inputFocused?: boolean;
  };

export type InputAddonProps = React.ComponentProps<typeof View> &
  VariantProps<typeof inputAddonVariants> & {
    children: React.ReactNode;
  };

export type InputAddonChild =
  | React.ReactElement<InputAddonProps>
  | null
  | false;
export type InputAddonChildren = InputAddonChild | InputAddonChild[];

type InputAddonIconProps = {
  children: React.ReactNode;
  className?: string;
};

type InputAddonButtonProps = Omit<React.ComponentProps<typeof Button>, "size"> &
  VariantProps<typeof inputAddonButtonVariants>;

type UseInputFocusStateProps = {
  onFocus?: (e: FocusEvent) => void;
  onBlur?: (e: BlurEvent) => void;
};

// Context
const InputAddonButtonContext =
  createContext<InternalInputAddonButtonContextType | null>(null);

const useInputAddonButtonContext = () => {
  const context = useContext(InputAddonButtonContext);
  if (!context) {
    throw new Error(
      "useInputAddonButtonContext must be used within a Button component"
    );
  }
  return context;
};

// Components
export const Input = ({ className, disabled, ...props }: InputProps) => {
  return (
    <RNTextInput
      className={cn(
        "grow font-normal text-base text-foreground leading-tight",
        className
      )}
      editable={!disabled}
      placeholderTextColorClassName="accent-muted-foreground"
      {...props}
    />
  );
};

export const InputGroup = ({
  children,
  disabled,
  invalid,
  focused,
  inputFocused = false,
  onPress,
  onPressIn,
  onPressOut,
  onLongPress,
  accessibilityRole,
  accessibilityState,
  accessibilityLabel,
  accessibilityHint,
  accessible,
  hitSlop,
  testID,
  delayLongPress,
  className,
  style,
  ...props
}: InputGroupProps) => {
  const [inputColor, ringColor, destructiveColor] = useCSSVariable([
    "--color-input",
    "--color-ring",
    "--color-destructive",
  ]) as [string, string, string];

  const outlineWidth = useSharedValue(1);
  const outlineColorProgress = useSharedValue(0);

  useEffect(() => {
    if (invalid) {
      outlineWidth.value = withTiming(2, { duration: ANIMATION_DURATION });
      outlineColorProgress.value = withTiming(2, {
        duration: ANIMATION_DURATION,
      });
    } else if (focused) {
      outlineWidth.value = withTiming(2, { duration: ANIMATION_DURATION });
      outlineColorProgress.value = withTiming(1, {
        duration: ANIMATION_DURATION,
      });
    } else {
      outlineWidth.value = withTiming(1, { duration: ANIMATION_DURATION });
      outlineColorProgress.value = withTiming(0, {
        duration: ANIMATION_DURATION,
      });
    }
  }, [focused, invalid, outlineWidth, outlineColorProgress]);

  const animatedStyle = useAnimatedStyle(() => {
    const color = interpolateColor(
      outlineColorProgress.value,
      [0, 1, 2],
      [inputColor, ringColor, destructiveColor]
    );
    return {
      outlineColor: color,
      outlineWidth: outlineWidth.value,
    };
  });

  const isPressable = Boolean(
    onPress ?? onPressIn ?? onPressOut ?? onLongPress
  );

  return (
    <Animated.View
      {...props}
      className={cn(
        "relative flex min-h-12 w-full flex-row items-center gap-2 rounded-lg border-continuous bg-card px-3 py-2",
        disabled && "opacity-50",
        className
      )}
      style={[animatedStyle, style]}
    >
      {children}
      {isPressable ? (
        <Pressable
          accessibilityHint={accessibilityHint}
          accessibilityLabel={accessibilityLabel}
          accessibilityRole={accessibilityRole}
          accessibilityState={accessibilityState}
          accessible={accessible}
          className="absolute inset-0 z-0 active:bg-accent/90 dark:active:bg-accent/50"
          delayLongPress={delayLongPress}
          disabled={disabled}
          hitSlop={hitSlop}
          onLongPress={onLongPress}
          onPress={onPress}
          onPressIn={onPressIn}
          onPressOut={onPressOut}
          pointerEvents={inputFocused ? "none" : "auto"}
          testID={testID}
        />
      ) : null}
    </Animated.View>
  );
};

export const InputAddon = ({ align, className, ...props }: InputAddonProps) => {
  return (
    <View
      className={cn(inputAddonVariants({ align }), className)}
      {...props}
      pointerEvents="box-none"
    />
  );
};

export const InputAddonIcon = ({
  children,
  ...props
}: InputAddonIconProps): React.ReactElement | null => {
  const child = Children.only(children);

  if (!child) {
    if (__DEV__) {
      throw new Error(
        "InputAddonIcon expects a single React element as children"
      );
    }
    return null;
  }

  return cloneElement(
    child as React.ReactElement<{ className?: string; pointerEvents?: "none" }>,
    {
      ...props,
      className: cn("size-6 text-muted-foreground", props.className),
      pointerEvents: "none",
    }
  );
};

export const InputAddonButton = ({
  className,
  variant = "ghost",
  size = "sm",
  disabled,
  busy,
  ...props
}: InputAddonButtonProps) => {
  const ctx = useMemo(() => ({ size, variant }), [size, variant]);
  return (
    <InputAddonButtonContext.Provider value={ctx}>
      <Button
        {...props}
        busy={busy}
        className={cn(inputAddonButtonVariants({ size }), className)}
        disabled={disabled}
        focusable={false}
        size={size}
        variant={variant}
      />
    </InputAddonButtonContext.Provider>
  );
};

export const InputAddonButtonText = (
  props: React.ComponentProps<typeof ButtonText>
) => {
  const ctx = useInputAddonButtonContext();
  return (
    <ButtonText
      {...props}
      className={cn(inputAddonButtonTextVariants(ctx), props.className)}
    />
  );
};

export const InputAddonButtonIcon = (
  props: React.ComponentProps<typeof ButtonIcon>
) => {
  const ctx = useInputAddonButtonContext();

  return (
    <ButtonIcon
      {...props}
      className={cn(inputAddonButtonIconVariants(ctx), props.className)}
    />
  );
};

// Hooks
export const useInputFocusState = ({
  onFocus,
  onBlur,
}: UseInputFocusStateProps) => {
  const [isFocused, setIsFocused] = useState(false);

  const internalRef = useRef<RNTextInput>(null);

  const handleFocus = useCallback(
    (e: FocusEvent) => {
      onFocus?.(e);

      setIsFocused(true);
    },
    [onFocus]
  );

  const handleBlur = useCallback(
    (e: BlurEvent) => {
      onBlur?.(e);

      setIsFocused(false);
    },
    [onBlur]
  );

  const handlePress = useCallback(() => internalRef.current?.focus(), []);

  return {
    handleBlur,
    handleFocus,
    handlePress,
    internalRef,
    isFocused,
  };
};

export const useInputAddons = (
  children?: InputAddonChildren | React.ReactElement | null
) => {
  const startAddons: InputAddonChild[] = [];
  const endAddons: InputAddonChild[] = [];

  Children.forEach(children, (child) => {
    if (isValidElement(child) && child.type === InputAddon) {
      const typedChild = child as InputAddonChild;

      if (typedChild) {
        if (
          typeof typedChild.props.align === "undefined" ||
          typedChild.props.align === "inline-start"
        ) {
          startAddons.push(typedChild);
        } else {
          endAddons.push(typedChild);
        }
      }
    }
  });

  return {
    endAddons,
    groupClassName: cn(
      startAddons.length && "pl-0",
      endAddons.length && "pr-0"
    ),
    startAddons,
  };
};

// Styles
const inputAddonVariants = cva(
  "relative z-10 flex items-center justify-center",
  {
    defaultVariants: {
      align: "inline-start",
    },
    variants: {
      align: {
        "inline-end": "pr-3",
        "inline-start": "pl-3",
      },
    },
  }
);

const inputAddonButtonVariants = cva("z-10 w-fit gap-1 shadow-none", {
  defaultVariants: {
    size: "sm",
  },
  variants: {
    size: { icon: "size-7", sm: "h-8 px-2" },
  },
});

const inputAddonButtonTextVariants = cva("text-sm", {
  defaultVariants: {
    variant: "default",
  },
  variants: {
    variant: {
      default: "text-primary-foreground",
      destructive: "text-white",
      ghost: "text-muted-foreground",
      link: "text-muted-foreground",
      outline: "text-muted-foreground",
      secondary: "text-secondary-foreground",
    },
  },
});

const inputAddonButtonIconVariants = cva("", {
  defaultVariants: {
    size: "sm",
  },
  variants: {
    size: {
      icon: "size-5",
      sm: "size-4",
    },
    variant: {
      default: "text-primary-foreground",
      destructive: "text-white",
      ghost: "text-muted-foreground",
      link: "text-muted-foreground",
      outline: "text-muted-foreground",
      secondary: "text-secondary-foreground",
    },
  },
});
